// brute: BFS po kwotach — warstwa i = kwoty osiągalne dokładnie i monetami
vector<ll> dist(k + 1, -1); dist[0] = 0; queue<ll> q; q.push(0);
while (!q.empty()) { ll s = q.front(); q.pop(); for (ll x : c) if (s + x <= k && dist[s + x] < 0) { dist[s + x] = dist[s] + 1; q.push(s + x); } }
if (dist[k] < 0) cout << "{{NONE}}" << "\n"; else cout << dist[k] << "\n";

